parameters.jsCode:
const slackEvent = $json.body?.event ?? $json;

const eventUser =
  slackEvent?.user ??
  $json.user ??
  '';

if (
  slackEvent?.bot_id ||
  slackEvent?.subtype === 'bot_message' ||
  eventUser === 'SLACK_BOT_USER_ID'
) {
  return [];
}
const rawInput =
  $json.message ??
  $json.text ??
  $json.body ??
  $json.input ??
  '';

let parsed = rawInput;

if (typeof rawInput === 'string') {
  try {
    parsed = JSON.parse(rawInput);
  } catch {
    parsed = null;
  }
}

const searchableText =
  typeof rawInput === 'string'
    ? rawInput.toLowerCase()
    : JSON.stringify(rawInput).toLowerCase();

let inputType = 'general';

if (parsed && typeof parsed === 'object') {
  const source = parsed._source ?? parsed;

  const decoderName = String(
    source?.decoder?.name ?? ''
  ).toLowerCase();

  const programName = String(
    source?.predecoder?.program_name ?? ''
  ).toLowerCase();

  const ruleGroups = Array.isArray(source?.rule?.groups)
    ? source.rule.groups.map(group => String(group).toLowerCase())
    : [];

  const winData = source?.data?.win;
  const winSystem = winData?.system;

  /*
   * Check specific embedded log sources first.
   * Do not classify every Wazuh document as wazuh_json.
   */

  if (
    winData ||
    winSystem?.eventID ||
    winSystem?.providerName ||
    decoderName === 'windows_eventchannel' ||
    ruleGroups.includes('windows') ||
    ruleGroups.includes('windows_security')
  ) {
    inputType = 'windows';

  } else if (
    decoderName.includes('fortigate') ||
    ruleGroups.some(group => group.includes('fortigate')) ||
    searchableText.includes('fortigate')
  ) {
    inputType = 'fortigate';

  } else if (
    decoderName.includes('paloalto') ||
    ruleGroups.some(group => group.includes('paloalto')) ||
    searchableText.includes('palo alto') ||
    searchableText.includes('pan-os')
  ) {
    inputType = 'paloalto';

  } else if (
    decoderName.includes('f5') ||
    ruleGroups.some(group => group.includes('f5')) ||
    searchableText.includes('f5-bigip') ||
    searchableText.includes('big-ip')
  ) {
    inputType = 'f5';

  /*
   * Route all supported Trend Micro CEF products to one CEF analyst:
   * - Deep Security
   * - Deep Discovery Inspector
   * - Apex Central / Apex One
   */

  } else if (
    (
      programName === 'cef' ||
      searchableText.includes('cef: 0|trend micro|') ||
      searchableText.includes('cef:0|trend micro|')
    ) &&
    (
      ruleGroups.includes('trendmicro') ||
      searchableText.includes('|trend micro|') ||
      searchableText.includes('deep security') ||
      searchableText.includes('deep discovery inspector') ||
      searchableText.includes('apex central') ||
      searchableText.includes('apex one')
    )
  ) {
    inputType = 'cef';

  } else if (
    decoderName.includes('linux') ||
    ruleGroups.includes('linux') ||
    searchableText.includes('/var/log/auth.log') ||
    searchableText.includes('sshd[')
  ) {
    inputType = 'linux';

  } else if (
    source?.rule ||
    source?.agent ||
    source?.manager ||
    source?.cluster ||
    String(parsed?._index ?? '').startsWith('wazuh-')
  ) {
    inputType = 'wazuh_json';
  }

} else {
  /*
   * Classification for plain-text logs and IOCs.
   */

  const ipv4Pattern =
    /\b(?:25[0-5]|2[0-4]\d|1?\d?\d)(?:\.(?:25[0-5]|2[0-4]\d|1?\d?\d)){3}\b/;

  const hashPattern =
    /\b(?:[a-f0-9]{32}|[a-f0-9]{40}|[a-f0-9]{64})\b/i;

  if (
    searchableText.includes('microsoft-windows-security-auditing') ||
    searchableText.includes('eventid') ||
    searchableText.includes('event id') ||
    searchableText.includes('windows security')
  ) {
    inputType = 'windows';

  } else if (
    searchableText.includes('fortigate') ||
    searchableText.includes('fortios')
  ) {
    inputType = 'fortigate';

  } else if (
    searchableText.includes('palo alto') ||
    searchableText.includes('pan-os')
  ) {
    inputType = 'paloalto';

  } else if (
    searchableText.includes('f5-bigip') ||
    searchableText.includes('big-ip') ||
    searchableText.includes('asm:')
  ) {
    inputType = 'f5';

  } else if (
    (
      searchableText.includes('cef: 0|trend micro|') ||
      searchableText.includes('cef:0|trend micro|')
    ) &&
    (
      searchableText.includes('deep security') ||
      searchableText.includes('deep discovery inspector') ||
      searchableText.includes('apex central') ||
      searchableText.includes('apex one') ||
      searchableText.includes('|trend micro|')
    )
  ) {
    inputType = 'cef';

  } else if (hashPattern.test(searchableText.trim())) {
    inputType = 'hash';

  } else if (
    ipv4Pattern.test(searchableText.trim()) &&
    searchableText.trim().split(/\s+/).length <= 3
  ) {
    inputType = 'ip';
  }
}

return [
  {
    json: {
      ...$json,
      input_type: inputType,
    },
  },
];
